"""Authorised device-local execution adapter. No hosted model can invoke this directly."""

from __future__ import annotations

import time
from collections.abc import Callable
from dataclasses import dataclass
from typing import Protocol

from selecta.lf_ai.contract import OPS, LucyPlan, Suggestion


@dataclass(frozen=True)
class EngineScope:
    """Authenticated host facts, never generated by the AI model."""

    workspace_id: str
    device_id: str
    actor_id: str
    generation: int
    recipe_revision: str

    def valid(self) -> bool:
        return (
            bool(self.workspace_id and self.device_id and self.actor_id)
            and type(self.generation) is int
            and self.generation >= 0
            and bool(self.recipe_revision)
        )


@dataclass(frozen=True)
class VerifiedRecording:
    """Agent 03's exact local match result, without exposing any device-local path."""

    recording_id: str
    state: str
    verified_at: float
    source_revision: str | None = None


@dataclass(frozen=True)
class ExecutionResult:
    status: str
    verified: tuple[str, ...] = ()
    blocked: tuple[str, ...] = ()
    applied: int = 0


class LocalEnginePort(Protocol):
    """Implemented ONLY by the authenticated local engine (Agents 03/05/07/08).

    For each action the engine must recheck recording bindings, authorise actor,
    scope, output/device permissions, generation and approvals. apply_suggestion
    must not infer permission from successful cloud planning.
    """

    def verify_exact(self, scope: EngineScope, recording_id: str) -> VerifiedRecording: ...
    def authorise(
        self,
        scope: EngineScope,
        suggestion: Suggestion,
        approval_token: str,
    ) -> bool: ...
    def apply_suggestion(self, scope: EngineScope, suggestion: Suggestion) -> None: ...


class LocalPlanExecutor:
    def __init__(
        self,
        port: LocalEnginePort,
        *,
        now: Callable[[], float] = time.time,
        max_verification_age: float = 30.0,
    ) -> None:
        if not 0 < max_verification_age <= 300:
            raise ValueError("verification age must be positive and bounded")
        self.port = port
        self.now = now
        self.max_verification_age = max_verification_age

    def inspect(
        self, plan: LucyPlan, scope: EngineScope, cancelled: Callable[[], bool] | None = None
    ) -> ExecutionResult:
        """Read-only verification; a cloud plan is NEVER an availability claim."""
        if not scope.valid() or (plan.workspace_id, plan.device_id) != (
            scope.workspace_id,
            scope.device_id,
        ):
            return ExecutionResult("scope_denied")
        if plan.schema_version != 1 or plan.availability != "unverified":
            return ExecutionResult("invalid_plan")
        if any(step.op not in OPS for step in plan.steps):
            return ExecutionResult("invalid_plan")
        refs = tuple(
            dict.fromkeys(recording for step in plan.steps for recording in step.recording_ids)
        )
        ready, blocked = [], []
        for recording in refs:
            if cancelled and cancelled():
                return ExecutionResult("cancelled", tuple(ready))
            verified = self.port.verify_exact(scope, recording)
            if (
                verified.recording_id == recording
                and verified.state == "ready"
                and 0 <= self.now() - verified.verified_at <= self.max_verification_age
            ):
                ready.append(recording)
            else:
                blocked.append(recording)
        return ExecutionResult(
            "verified" if not blocked else "unavailable",
            tuple(ready),
            tuple(blocked),
        )

    def apply(
        self,
        plan: LucyPlan,
        scope: EngineScope,
        *,
        approval_token: str,
        cancelled: Callable[[], bool] | None = None,
    ) -> ExecutionResult:
        """Host-approved proposals only; never play/stop/delete/audio/DSP from an AI turn.

        This is NOT a cloud RPC. The engine must independently authorise and
        revalidate each action immediately before applying it, particularly after
        an offline period or a device ownership-generation change.
        """
        checked = self.inspect(plan, scope, cancelled)
        if checked.status != "verified":
            return checked
        if not isinstance(approval_token, str) or not approval_token:
            return ExecutionResult("approval_required", checked.verified)
        for step in plan.steps:
            if cancelled and cancelled():
                return ExecutionResult("cancelled", checked.verified)
            if not self.port.authorise(scope, step, approval_token):
                return ExecutionResult("permission_denied", checked.verified)
        # All actions are inert proposal edits, never playback or DSP. Every
        # adapter is expected to commit atomically under its own revision lock.
        count = 0
        for step in plan.steps:
            if cancelled and cancelled():
                return ExecutionResult("cancelled", checked.verified, applied=count)
            if step.op == "explain":
                continue
            self.port.apply_suggestion(scope, step)
            count += 1
        return ExecutionResult("applied", checked.verified, applied=count)
